INSERT INTO `informasi` (`id_informasi`, `id_kategori`, `id_user`, `judul`, `slug`, `ringkasan`, `isi`, `gambar`, `tanggal_publikasi`, `penulis`, `status`, `created_at`, `updated_at`) VALUES
  (1, 1, 1, 'Sosialisasi PBB-P2 di Kecamatan Tirtamulya', 'sosialisasi-pbb-p2-di-kecamatan-tirtamulya', 'Bapenda Karawang menggelar sosialisasi terkait tata cara pembayaran dan pengamanan PBB-P2 di Kecamatan Tirtamulya.', 'Badan Pendapatan Daerah (BAPENDA) Kabupaten Karawang melaksanakan kegiatan sosialisasi optimalisasi penerimaan Pajak Bumi dan Bangunan Perdesaan dan Perkotaan (PBB-P2) di Aula Kantor Kecamatan Tirtamulya pada Jumat, 16 Oktober 2026. Kegiatan ini dihadiri langsung oleh jajaran pejabat BAPENDA, Camat Tirtamulya, serta para Kepala Desa dan kolektor pajak se-Kecamatan Tirtamulya. Materi utama yang disampaikan meliputi tata cara pembayaran digital melalui QRIS dan kanal perbankan mitra, percepatan distribusi SPPT, serta rekonsiliasi data ketetapan dan penerimaan desa.', 'berita-1.jpg', '2026-10-16 09:00:00', 'Humas BAPENDA Karawang', 'Publik', '2026-11-16 14:48:05', '2026-11-16 14:48:05'),
  (2, 1, 1, 'Peningkatan Layanan Cek PBB Online', 'peningkatan-layanan-cek-pbb-online', 'Kini masyarakat dapat mengecek tagihan PBB-P2 secara lebih mudah dan transparan melalui website resmi BAPENDA Karawang.', 'Untuk meningkatkan kepuasan wajib pajak, BAPENDA Karawang meluncurkan pembaruan portal PBB-P2 Online. Sistem ini memungkinkan warga mengecek ketetapan pajak hanya dengan memasukkan 18 digit Nomor Objek Pajak (NOP), memantau riwayat pembayaran hingga 5 tahun terakhir, dan mencetak bukti pembayaran digital secara langsung.', 'berita-2.jpg', '2026-10-10 10:30:00', 'Humas BAPENDA Karawang', 'Publik', '2026-11-16 14:48:05', '2026-11-16 14:48:05'),
  (3, 1, 1, 'Realisasi PBB-P2 Triwulan III Capai 76,6%', 'realisasi-pbb-p2-triwulan-iii-capai-76-6', 'Realisasi penerimaan PBB-P2 hingga Triwulan III tahun 2026 mencapai 76,6% dari target yang ditetapkan.', 'BAPENDA Kabupaten Karawang mencatatkan capaian positif penerimaan PBB-P2 hingga penutupan Triwulan III 2026 sebesar 76,6%. Peningkatan ini didorong oleh integrasi sistem monitoring berbasis geospasial serta tingginya partisipasi masyarakat dalam program pembebasan denda administratif.', 'berita-3.jpg', '2026-10-05 14:00:00', 'Humas BAPENDA Karawang', 'Publik', '2026-11-16 14:48:05', '2026-11-16 14:48:05'),
  (4, 2, 1, 'Jadwal Pembayaran PBB-P2 Tahap IV Tahun 2026', 'jadwal-pembayaran-pbb-p2-tahap-iv-tahun-2026', 'Diberitahukan kepada seluruh Wajib Pajak bahwa loket pembayaran dibuka mulai 15 Oktober 2026 hingga 15 Desember 2026.', 'Diberitahukan kepada seluruh Wajib Pajak PBB-P2 di Kabupaten Karawang bahwa loket layanan pembayaran Pajak Bumi dan Bangunan Tahap IV dibuka mulai tanggal 15 Oktober 2026 hingga 15 Desember 2026. Pembayaran dapat dilakukan melalui loket kantor BAPENDA Karawang, mobil layanan keliling di setiap kantor kecamatan, Bank BJB teller, ATM, mobile banking, serta seluruh minimarket mitra (Indomaret dan Alfamart). Pastikan melakukan pembayaran sebelum jatuh tempo guna menghindari denda keterlambatan administrasi.', NULL, '2026-10-14 08:00:00', 'Bidang PBB dan BPHTB BAPENDA', 'Publik', '2026-11-16 14:48:05', '2026-11-16 14:48:05'),
  (5, 2, 1, 'Perpanjangan Layanan Cek PBB Online (Info Pemeliharaan)', 'perpanjangan-layanan-cek-pbb-online-info-pemeliharaan', 'Pemeliharaan server berkala akan dilakukan pada Sabtu dini hari pukul 00.00 - 04.00 WIB.', 'Sehubungan dengan optimalisasi infrastruktur cloud BAPENDA Karawang, akan dilaksanakan pemeliharaan server berkala pada hari Sabtu, 17 Oktober 2026 pukul 00:00 hingga 04:00 WIB. Layanan cek PBB online akan sementara waktu tidak dapat diakses selama proses tersebut berlangsung.', NULL, '2026-10-08 11:00:00', 'Bidang PBB dan BPHTB BAPENDA', 'Publik', '2026-11-16 14:48:05', '2026-11-16 14:48:05'),
  (6, 2, 1, 'Himbauan Pembayaran PBB-P2 Tepat Waktu', 'himbauan-pembayaran-pbb-p2-tepat-waktu', 'Mari dukung percepatan pembangunan Kabupaten Karawang dengan taat membayar pajak bumi dan bangunan tepat waktu.', 'Pajak yang Anda bayarkan dikembalikan dalam bentuk perbaikan infrastruktur jalan, jembatan, fasilitas kesehatan, serta beasiswa pendidikan putra-putri Karawang. Mari sukseskan pembangunan daerah dengan taat membayar pajak!', NULL, '2026-10-01 08:30:00', 'Bidang PBB dan BPHTB BAPENDA', 'Publik', '2026-11-16 14:48:05', '2026-11-16 14:48:05'),
  (7, 3, 1, 'Perda Kab. Karawang No. 11 Tahun 2021 (Perubahan atas Perda No. 16 Tahun 2016)', 'perda-kab-karawang-no-11-tahun-2021', 'Peraturan Daerah tentang Pajak Daerah dan Retribusi Daerah Kabupaten Karawang.', 'Peraturan Daerah Kabupaten Karawang Nomor 11 Tahun 2021 mengatur tentang perubahan tarif, klasifikasi objek bumi dan bangunan, serta skema insentif pajak daerah bagi perdesaan dan perkotaan di lingkungan Kabupaten Karawang.', NULL, '2026-09-01 08:00:00', 'Bagian Hukum Setda Karawang', 'Publik', '2026-11-16 14:48:05', '2026-11-16 14:48:05'),
  (8, 3, 1, 'Perbup Karawang No. 77 Tahun 2021 tentang Tata Cara Pembayaran PBB-P2', 'perbup-karawang-no-77-tahun-2021', 'Petunjuk teknis pemungutan, penagihan, dan pembayaran Pajak Bumi dan Bangunan Perdesaan dan Perkotaan.', 'Peraturan Bupati Karawang Nomor 77 Tahun 2021 mengatur tentang petunjuk teknis pelaksanaan administrasi pemungutan PBB-P2, hak dan kewajiban kolektor desa, serta mekanisme verifikasi pembayaran elektronik.', NULL, '2026-08-15 08:00:00', 'Bagian Hukum Setda Karawang', 'Publik', '2026-11-16 14:48:05', '2026-11-16 14:48:05'),
  (9, 4, 1, 'Bagaimana Cara Cek PBB Online?', 'bagaimana-cara-cek-pbb-online', 'Panduan cepat pengecekan status ketetapan dan tunggakan PBB online.', 'Untuk mengecek tagihan PBB-P2 secara online di Kabupaten Karawang:\n1. Kunjungi portal resmi BAPENDA Karawang atau menu Peta PBB-P2 / Cek PBB pada dashboard ini.\n2. Masukkan 18 digit Nomor Objek Pajak (NOP) yang tercantum pada lembar SPPT PBB Anda.\n3. Pilih tahun pajak yang ingin diperiksa (misalnya 2026).\n4. Klik tombol "Cari" atau "Cek Tagihan" untuk melihat rincian jumlah ketetapan, realisasi pembayaran, dan sisa tagihan secara real-time.', NULL, '2026-09-10 10:00:00', 'Pusat Bantuan BAPENDA Karawang', 'Publik', '2026-11-16 14:48:05', '2026-11-16 14:48:05'),
  (10, 4, 1, 'Bagaimana Cara Melihat Tagihan PBB-P2?', 'bagaimana-cara-melihat-tagihan-pbb-p2', 'Kanal resmi melihat rincian ketetapan SPPT PBB.', 'Tagihan PBB-P2 dapat dilihat melalui:\n1. Surat Pemberitahuan Pajak Terhutang (SPPT) fisik yang dibagikan oleh petugas desa/kelurahan atau RT/RW setempat setiap awal tahun pajak.\n2. Fitur Cek Tagihan PBB Online pada portal BAPENDA Kabupaten Karawang.\n3. Aplikasi perbankan digital (Mobile Banking Bank BJB, Mandiri, BCA, BRI, BNI) dengan memasukkan NOP pada menu Pembayaran Pajak Daerah.', NULL, '2026-09-12 10:00:00', 'Pusat Bantuan BAPENDA Karawang', 'Publik', '2026-11-16 14:48:05', '2026-11-16 14:48:05'),
  (11, 4, 1, 'Bagaimana Cara Melakukan Pembayaran?', 'bagaimana-cara-melakukan-pembayaran', 'Pilihan metode pembayaran tunai maupun nontunai resmi.', 'Pembayaran PBB-P2 Kabupaten Karawang dapat dilakukan melalui berbagai kanal resmi yang mudah diakses:\n1. Bank BJB (Teller, ATM, BJB Digi, dan QRIS)\n2. Kantor Pos Indonesia di seluruh cabang\n3. Gerai minimarket retail (Indomaret dan Alfamart)\n4. Platform E-Commerce dan Dompet Digital (Tokopedia, Bukalapak, Shopee, Gopay, OVO, Dana)\n5. Petugas Kolektor Pajak resmi di kantor Desa/Kelurahan setempat.', NULL, '2026-09-15 10:00:00', 'Pusat Bantuan BAPENDA Karawang', 'Publik', '2026-11-16 14:48:05', '2026-11-16 14:48:05');
